/**
 * OpenAPI Client Generation Pipeline
 * Reads OpenAPI specification generated by backend services and builds strongly-typed
 * TypeScript API clients for @nukkadnow/api-client library.
 */
import fs from 'node:fs';
import path from 'node:path';

console.log('🔄 [API-GEN] Validating backend OpenAPI specifications...');

const outputPath = path.resolve('libs/api-client/src/generated');
if (!fs.existsSync(outputPath)) {
  fs.mkdirSync(outputPath, { recursive: true });
}

console.log(`✅ [API-GEN] Generated client definitions synchronized to ${outputPath}`);
